insert into transaction_types(abbreviation,name,module_category,description)values('COT_PRO','Cotización de Proveedor','Compras','Cotización recibida de un proveedor.'),('REC_INV','Recepción de Inventario','Compras','Recepción física de artículos de una orden de compra.')on conflict(abbreviation)do update set name=excluded.name,module_category=excluded.module_category,description=excluded.description;
create table if not exists purchase_document(document_id bigint generated always as identity primary key,document_type text not null check(document_type in('REQUISITION','QUOTE','ORDER','RECEIPT')),document_number text not null unique,document_date date not null,valid_until date,supplier_id bigint references suppliers,subsidiary_id bigint not null references subsidiaries,currency_id bigint not null references currencies,exchange_rate numeric(24,10)not null default 1,fiscal_period_id bigint not null references fiscal_periods,location_id bigint references locations,payment_term_id bigint references payment_terms,source_document_id bigint references purchase_document,status text not null default'BORRADOR',memo text,total_amount numeric(24,6)not null default 0,transaction_id bigint references "transaction",created_by bigint references users,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists purchase_document_line(line_id bigint generated always as identity primary key,document_id bigint not null references purchase_document on delete cascade,line_number int not null,product_id bigint references products,account_id bigint references chart_accounts,description text,quantity numeric(24,6)not null check(quantity>0),unit_cost numeric(24,6)not null check(unit_cost>=0),tax_code_id bigint references tax_codes,tax_rate numeric(12,6)not null default 0,tax_amount numeric(24,6)not null default 0,gross_amount numeric(24,6)not null,department_id bigint references departments,cost_center_id bigint references cost_centers,class_id bigint references classes,financial_creditor_id bigint references financial_creditors,related_company_id bigint references related_companies,unique(document_id,line_number));
alter table purchase_document enable row level security;alter table purchase_document_line enable row level security;drop policy if exists purchase_document_access on purchase_document;create policy purchase_document_access on purchase_document for select to authenticated using(subsidiary_id=active_subsidiary_id());drop policy if exists purchase_document_line_access on purchase_document_line;create policy purchase_document_line_access on purchase_document_line for select to authenticated using(exists(select 1 from purchase_document d where d.document_id=purchase_document_line.document_id and d.subsidiary_id=active_subsidiary_id()));
create or replace function purchase_workflow_options()returns jsonb language sql stable security definer set search_path=public as $$select jsonb_build_object('subsidiary',jsonb_build_object('id',s.subsidiary_id,'name',s.name,'currencyId',s.currency_id),'suppliers',coalesce((select jsonb_agg(jsonb_build_object('id',p.supplier_id,'name',p.company_name,'paymentTermId',p.payment_term_id))from suppliers p join entity_subsidiaries es using(supplier_id)where es.subsidiary_id=s.subsidiary_id),'[]'),'products',coalesce((select jsonb_agg(jsonb_build_object('id',p.product_id,'code',p.item_code,'name',p.display_name,'cost',p.purchase_cost,'accountId',p.purchase_account_id))from products p join product_subsidiaries ps using(product_id)where ps.subsidiary_id=s.subsidiary_id and ps.is_active and p.is_active and p.product_usage in('Compra','Ambas')),'[]'),'currencies',(select jsonb_agg(jsonb_build_object('id',currency_id,'code',currency_code))from currencies),'periods',coalesce((select jsonb_agg(jsonb_build_object('id',fiscal_period_id,'name',period_name,'start',start_date,'end',end_date))from fiscal_periods where subsidiary_id=s.subsidiary_id and not is_closed and not coalesce(ap_closed,false)),'[]'),'locations',coalesce((select jsonb_agg(jsonb_build_object('id',l.location_id,'name',l.name))from locations l left join location_subsidiaries ls using(location_id)where l.subsidiary_id=s.subsidiary_id or ls.subsidiary_id=s.subsidiary_id),'[]'),'terms',(select coalesce(jsonb_agg(jsonb_build_object('id',term_id,'name',term_name)),'[]')from payment_terms),'taxes',(select coalesce(jsonb_agg(jsonb_build_object('id',tax_code_id,'name',code_name,'rate',rate_percentage)),'[]')from tax_codes),'sources',coalesce((select jsonb_agg(jsonb_build_object('id',document_id,'type',document_type,'number',document_number,'supplierId',supplier_id))from purchase_document where subsidiary_id=s.subsidiary_id and status<>'CANCELADO'),'[]'))from subsidiaries s where s.subsidiary_id=active_subsidiary_id()$$;
create or replace function save_purchase_document(p_payload jsonb,p_document_id bigint default null)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare sid bigint:=active_subsidiary_id();did bigint:=p_document_id;kind text:=p_payload->>'type';abbr text;tt bigint;st bigint;num text;tid bigint;line jsonb;n int:=0;total numeric:=0;tax numeric;gross numeric;begin if kind not in('REQUISITION','QUOTE','ORDER','RECEIPT')then raise exception'Tipo de documento inválido.';end if;if jsonb_array_length(coalesce(p_payload->'lines','[]'))=0 then raise exception'Agregue al menos una línea.';end if;if kind<>'REQUISITION'and nullif(p_payload->>'supplier_id','')is null then raise exception'Seleccione un proveedor.';end if;abbr:=case kind when'REQUISITION'then'REQ_COM'when'QUOTE'then'COT_PRO'when'ORDER'then'ORD_COM'else'REC_INV'end;select transaction_type_id into tt from transaction_types where abbreviation=abbr;select status_id into st from status order by case upper(code)when'APROBADO'then 1 else 2 end limit 1;for line in select value from jsonb_array_elements(p_payload->'lines')loop tax:=round((line->>'quantity')::numeric*(line->>'unit_cost')::numeric*coalesce(nullif(line->>'tax_rate','')::numeric,0)/100,6);total:=total+(line->>'quantity')::numeric*(line->>'unit_cost')::numeric+tax;end loop;if did is null then begin num:=next_transaction_number(tt,sid);exception when others then num:=abbr||'-'||to_char(clock_timestamp(),'YYYYMMDDHH24MISSMS');end;insert into "transaction"(tran_number,tran_date,transaction_type_id,subsidiary_id,currency_id,exchange_rate,fiscal_period_id,total_amount,status_id,supplier_id,payment_term_id)values(num,(p_payload->>'date')::date,tt,sid,(p_payload->>'currency_id')::bigint,(p_payload->>'rate')::numeric,(p_payload->>'period_id')::bigint,total,st,nullif(p_payload->>'supplier_id','')::bigint,nullif(p_payload->>'payment_term_id','')::bigint)returning transaction_id into tid;insert into purchase_document(document_type,document_number,document_date,valid_until,supplier_id,subsidiary_id,currency_id,exchange_rate,fiscal_period_id,location_id,payment_term_id,source_document_id,status,memo,total_amount,transaction_id,created_by)values(kind,num,(p_payload->>'date')::date,nullif(p_payload->>'valid_until','')::date,nullif(p_payload->>'supplier_id','')::bigint,sid,(p_payload->>'currency_id')::bigint,(p_payload->>'rate')::numeric,(p_payload->>'period_id')::bigint,nullif(p_payload->>'location_id','')::bigint,nullif(p_payload->>'payment_term_id','')::bigint,nullif(p_payload->>'source_id','')::bigint,coalesce(nullif(p_payload->>'status',''),'BORRADOR'),p_payload->>'memo',total,tid,app_user_id())returning document_id into did;else select transaction_id,document_number into tid,num from purchase_document where document_id=did and subsidiary_id=sid for update;if tid is null then raise exception'Documento no encontrado.';end if;delete from purchase_document_line where document_id=did;update purchase_document set document_date=(p_payload->>'date')::date,valid_until=nullif(p_payload->>'valid_until','')::date,supplier_id=nullif(p_payload->>'supplier_id','')::bigint,currency_id=(p_payload->>'currency_id')::bigint,exchange_rate=(p_payload->>'rate')::numeric,fiscal_period_id=(p_payload->>'period_id')::bigint,location_id=nullif(p_payload->>'location_id','')::bigint,payment_term_id=nullif(p_payload->>'payment_term_id','')::bigint,source_document_id=nullif(p_payload->>'source_id','')::bigint,status=p_payload->>'status',memo=p_payload->>'memo',total_amount=total,updated_at=now()where document_id=did;update "transaction"set tran_date=(p_payload->>'date')::date,total_amount=total where transaction_id=tid;end if;for line in select value from jsonb_array_elements(p_payload->'lines')loop n:=n+1;tax:=round((line->>'quantity')::numeric*(line->>'unit_cost')::numeric*coalesce(nullif(line->>'tax_rate','')::numeric,0)/100,6);gross:=(line->>'quantity')::numeric*(line->>'unit_cost')::numeric+tax;insert into purchase_document_line(document_id,line_number,product_id,account_id,description,quantity,unit_cost,tax_code_id,tax_rate,tax_amount,gross_amount,department_id,cost_center_id,class_id,financial_creditor_id,related_company_id)values(did,n,nullif(line->>'product_id','')::bigint,nullif(line->>'account_id','')::bigint,line->>'description',(line->>'quantity')::numeric,(line->>'unit_cost')::numeric,nullif(line->>'tax_code_id','')::bigint,coalesce(nullif(line->>'tax_rate','')::numeric,0),tax,gross,nullif(line->>'department_id','')::bigint,nullif(line->>'cost_center_id','')::bigint,nullif(line->>'class_id','')::bigint,nullif(line->>'financial_creditor_id','')::bigint,nullif(line->>'related_company_id','')::bigint);if kind='RECEIPT'and nullif(line->>'product_id','')is not null then insert into stock_movements(movement_date,transaction_id,product_id,location_id,quantity,movement_type,unit_cost)values((p_payload->>'date')::date,tid,(line->>'product_id')::bigint,(p_payload->>'location_id')::bigint,(line->>'quantity')::numeric,'RECEPCION_COMPRA',(line->>'unit_cost')::numeric);end if;end loop;return jsonb_build_object('id',did,'number',num);end$$;
create or replace function purchase_document_report(p_filters jsonb)returns jsonb language sql stable security definer set search_path=public as $$select jsonb_build_object('rows',coalesce(jsonb_agg(jsonb_build_object('id',d.document_id,'number',d.document_number,'date',d.document_date,'type',d.document_type,'supplier',s.company_name,'currency',c.currency_code,'total',d.total_amount,'status',d.status,'source',src.document_number)order by d.document_date desc,d.document_id desc),'[]'))from purchase_document d left join suppliers s on s.supplier_id=d.supplier_id join currencies c on c.currency_id=d.currency_id left join purchase_document src on src.document_id=d.source_document_id where d.subsidiary_id=active_subsidiary_id()and d.document_type=p_filters->>'type'and d.document_date between(p_filters->>'from')::date and(p_filters->>'to')::date$$;
create or replace function purchase_document_detail(p_document_id bigint)returns jsonb language sql stable security definer set search_path=public as $$select jsonb_build_object('header',to_jsonb(d),'lines',coalesce((select jsonb_agg(to_jsonb(l)order by line_number)from purchase_document_line l where l.document_id=d.document_id),'[]'))from purchase_document d where d.document_id=p_document_id and d.subsidiary_id=active_subsidiary_id()$$;
create or replace function delete_purchase_document(p_document_id bigint)returns boolean language plpgsql security definer set search_path=public,pg_temp as $$declare d purchase_document%rowtype;begin select*into d from purchase_document where document_id=p_document_id and subsidiary_id=active_subsidiary_id()for update;if exists(select 1 from purchase_document where source_document_id=p_document_id)then raise exception'El documento tiene transacciones posteriores relacionadas.';end if;delete from stock_movements where transaction_id=d.transaction_id;delete from purchase_document where document_id=p_document_id;delete from "transaction"where transaction_id=d.transaction_id;return true;end$$;
revoke all on function purchase_workflow_options(),save_purchase_document(jsonb,bigint),purchase_document_report(jsonb),purchase_document_detail(bigint),delete_purchase_document(bigint)from public,anon;grant execute on function purchase_workflow_options(),save_purchase_document(jsonb,bigint),purchase_document_report(jsonb),purchase_document_detail(bigint),delete_purchase_document(bigint)to authenticated;notify pgrst,'reload schema';
